package com.store.servlet;
import com.store.dao.PersonDAO;import com.store.model.Person;import java.io.IOException;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
@WebServlet(urlPatterns={"/customers","/suppliers"}) public class PersonServlet extends HttpServlet{ protected void doGet(HttpServletRequest r,HttpServletResponse h)throws ServletException,IOException{ String type=r.getServletPath().contains("suppliers")?"suppliers":"customers"; PersonDAO dao=new PersonDAO(type); String del=r.getParameter("delete"); if(del!=null){dao.delete(Integer.parseInt(del)); h.sendRedirect(type); return;} r.setAttribute("type",type); r.setAttribute("persons",dao.getAll()); r.getRequestDispatcher("persons.jsp").forward(r,h);} protected void doPost(HttpServletRequest r,HttpServletResponse h)throws IOException{ String type=r.getServletPath().contains("suppliers")?"suppliers":"customers"; Person p=new Person(); p.setName(r.getParameter("name")); p.setPhone(r.getParameter("phone")); p.setEmail(r.getParameter("email")); p.setAddress(r.getParameter("address")); new PersonDAO(type).save(p); h.sendRedirect(type); }}
